import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {decode, ID} from './protocol.mjs';
import {Pieces, TrackMapper, trackValidation} from './track.mjs';
import {Game} from './game.mjs';
import {ReplayCar, validate} from './trace.mjs';

// Independent hardware recording, not generated by the simulator. Replay checks
// host behavior and decoded geometry; it cannot prove movement or physical STOP.
const load = path => JSON.parse(readFileSync(new URL(path, import.meta.url)));
const trace = validate(load('./fixtures/groundshock-sdk-repaired-scan.json'));
const pieces = load('./data/pieces.json');
const scanStart = trace.markers.find(m => m.kind === 'scan-start').timeMs;
const bytes = hex => Uint8Array.from(hex.split(' ').map(b => parseInt(b, 16)));
const expectedOrder = [
  [33, false], [18, false], [57, true], [39, false], [20, false],
  [17, false], [17, true], [23, false], [36, false], [18, false], [34, false]
];
const motionSpeed = packet => new DataView(packet.buffer, packet.byteOffset, packet.byteLength).getInt16(2, true);

function replayMap() {
  const mapper = new TrackMapper(new Pieces(pieces));
  let firstClosureAt, firstOpticalIndex, positions = 0, transitions = 0;
  for (const [index, [at, car, direction, hex]] of trace.events.entries()) {
    if (at < scanStart || car !== 0 || direction !== 'rx') continue;
    for (const message of decode(bytes(hex))) {
      if (message.type === 'position') positions++;
      if (message.type === 'transition') transitions++;
      if (message.type === 'position' || message.type === 'transition') firstOpticalIndex ??= index;
      if (mapper.feed(message)) firstClosureAt ??= at;
    }
  }
  return {track: mapper.track, firstClosureAt, firstOpticalIndex, positions, transitions};
}

test('repaired Groundshock capture maps the observed 11-piece order without inferred sections', () => {
  const {track, firstClosureAt, positions, transitions} = replayMap();
  assert.equal(trace.dropped, 0);
  assert.equal(trace.cars[0].firmware, 11866);
  assert.deepEqual([positions, transitions], [24, 12]);
  assert.ok(track);
  assert.deepEqual(track.pieces.map(p => [p.id, p.reverse]), expectedOrder);
  assert.equal(track.count, 11);
  assert.equal(track.inferredCount, 0);
  assert.equal(track.closed, true);
  assert.ok(track.gap < 1e-6);
  assert.ok(Math.abs(track.length - 4878.8) < 1e-6);
  assert.equal(firstClosureAt, 39114);
  // Recognizing Power Zone's ID/geometry does not validate its special effects.
  assert.equal(track.unverifiedCount, 1);
  const checks = trackValidation(track);
  assert.deepEqual(checks.special, [{id:57, index:2}]);
  assert.equal(checks.physicalValidation, false);
});

test('successful scan wire evidence has no lane request, no pre-optical offset, and STOP after map closure', () => {
  const {firstClosureAt, firstOpticalIndex} = replayMap();
  const tx = trace.events.flatMap(([at, car, direction, hex], index) =>
    at >= scanStart && car === 0 && direction === 'tx' ? [{at, index, packet:bytes(hex)}] : []);
  assert.equal(tx.some(e => e.packet[1] === ID.CHANGE_LANE), false);
  const offsets = tx.filter(e => e.packet[1] === ID.SET_OFFSET);
  assert.equal(offsets.length, 1);
  // Position and calibration share a rounded timestamp; event order matters.
  assert.ok(offsets.every(e => e.index > firstOpticalIndex));
  const speedWrites = tx.filter(e => e.packet[1] === ID.SPEED);
  assert.deepEqual(speedWrites.filter(e => motionSpeed(e.packet) > 0).map(e => motionSpeed(e.packet)), [300]);
  const finalStop = speedWrites.find(e => e.at >= firstClosureAt && motionSpeed(e.packet) === 0);
  assert.ok(finalStop);
  assert.equal(finalStop.at - firstClosureAt, 2, 'recorded host-write completion, not physical stop latency');
  assert.equal(speedWrites.some(e => e.at > finalStop.at && motionSpeed(e.packet) > 0), false);
  assert.equal(trace.diagnostics.cars[0].physicalStopVerified, false);
});

test('real scan notifications make the current Game stop at closure and preserve Power Zone scoring gate', async () => {
  let now = 0;
  const radio = new ReplayCar(trace, 0);
  const game = new Game({pieces, weapons:load('./data/weapons.json'), vehicles:load('./data/vehicles.json'), clock:() => now});
  const driver = game.addCar(radio, {name:'Groundshock', model:8, simulated:false});
  await driver.car.initialization;
  await driver.car.pumpPromise;
  // Startup handshake is covered separately; replay this recorded SDK session
  // from its stopped scan boundary without pretending ReplayCar is firmware.
  now = scanStart; radio.advance(now); radio.initializationProfile = 'sdk';
  game.topSpeed = 300; game.startScan(driver); await driver.car.pumpPromise;
  const writesAtStart = radio.written.length;
  assert.equal(driver.car.speed, 300);
  assert.equal(radio.written.some(p => p[1] === ID.CHANGE_LANE), false);
  assert.equal(radio.written.some(p => p[1] === ID.SET_OFFSET), false);
  for (const [at] of trace.events) {
    if (at < scanStart) continue;
    now = at; radio.advance(now); game.tick(.04, now); await driver.car.pumpPromise;
  }
  assert.equal(game.phase, 'ready');
  assert.equal(game.halted, true);
  assert.equal(game.scanner, null);
  assert.equal(game.pitReason, null);
  assert.deepEqual(game.track.pieces.map(p => [p.id, p.reverse]), expectedOrder);
  assert.equal(driver.car.speed, 0);
  assert.equal(radio.written.at(-1)[1], ID.SPEED);
  assert.equal(motionSpeed(radio.written.at(-1)), 0);
  assert.equal(radio.written.slice(writesAtStart).some(p => p[1] === ID.SPEED && motionSpeed(p) > 0), false);
  assert.throws(() => game.startBattle(), /Special track pieces are unverified/);
});
